(318183, 23802, 1202, '<td valign="top">Your treatment of this picture makes it look out of focus and grainy on my monitor.I do like the idea of the shadowthough, but not the quality of the result.  5</td>', 'Your treatment of this picture makes it look out of focus and grainy on my monitor.I do like the idea of the shadowthough, but not the quality of the result.  5', '2003-06-07 10:50:00.000000', NULL, 1),
(318184, 23187, 1202, '<td valign="top">Nothing in the picture that makes me think liquid, a stretch of your imagination.  I have done that too, but it didn''t work for me either.  Pretty but a bit noisy.  4</td>', 'Nothing in the picture that makes me think liquid, a stretch of your imagination.  I have done that too, but it didn''t work for me either.  Pretty but a bit noisy.  4', '2003-06-07 10:52:24.000000', NULL, 1),
