(318190, 23606, 1202, '<td valign="top">A well execut4ed dhot with a certain degree of mystery that stirs the imagination.  I might have liked it a little brighter, but real nice as is.  Did you haave it balanced at 45 degrees or was it fastened.   8</td>', 'A well execut4ed dhot with a certain degree of mystery that stirs the imagination.  I might have liked it a little brighter, but real nice as is.  Did you haave it balanced at 45 degrees or was it fastened.   8', '2003-06-07 10:58:57.000000', NULL, 1),
(318191, 23709, 8500, '<td valign="top">Really good it''s even beautiful fo a so sad pic , maybe i would have cut the nose ...but it''s stille really cute ;)</td>', 'Really good it''s even beautiful fo a so sad pic , maybe i would have cut the nose ...but it''s stille really cute ;)', '2003-06-07 10:59:03.000000', NULL, 1),
(318192, 23596, 1202, '<td valign="top">Without you title I don''t think I would have thought of liquid.  Not a lot of POP here either. Sorry.  3</td>', 'Without you title I don''t think I would have thought of liquid.  Not a lot of POP here either. Sorry.  3', '2003-06-07 11:00:41.000000', NULL, 1),
(318193, 23282, 1202, '<td valign="top">Interesting picture of ooozing looking stuff.  Could it be liquid? I guess so.  7</td>', 'Interesting picture of ooozing looking stuff.  Could it be liquid? I guess so.  7', '2003-06-07 11:02:23.000000', NULL, 1),
