(319900, 23763, 9262, '<td valign="top">Enjoyed the colors.</td>', 'Enjoyed the colors.', '2003-06-09 17:44:52.000000', NULL, 1),
(319901, 23607, 9262, '<td valign="top">Nice perspective</td>', 'Nice perspective', '2003-06-09 17:45:28.000000', NULL, 1),
