(319905, 23224, 9262, '<td valign="top">Creative shot</td>', 'Creative shot', '2003-06-09 17:47:57.000000', NULL, 1),
(319906, 23708, 6870, '<td valign="top">The simple composition works here pretty well. The challenge did specify no water, though...</td>', 'The simple composition works here pretty well. The challenge did specify no water, though...', '2003-06-09 17:48:02.000000', NULL, 1),
