(319972, 23383, 6900, '<td valign="top">I''m thinking she''s not enjoying her liquids very much.</td>', 'I''m thinking she''s not enjoying her liquids very much.', '2003-06-09 18:45:26.000000', NULL, 1),
(319973, 23471, 6870, '<td valign="top">Fun shapes and tones here make an intriquing photo! I feel it would be enhanced with sharper focus to really bring out the clarity of the lines, and perhaps some more saturated colors.</td>', 'Fun shapes and tones here make an intriquing photo! I feel it would be enhanced with sharper focus to really bring out the clarity of the lines, and perhaps some more saturated colors.', '2003-06-09 18:45:53.000000', NULL, 1),
