(319975, 23198, 6900, '<td valign="top">Great action and interesting subject.</td>', 'Great action and interesting subject.', '2003-06-09 18:46:31.000000', NULL, 1),
(319976, 23553, 6900, '<td valign="top">Why is the plant in the background?   The reflections along the top and left are a bit distracting to this interesting subject.</td>', 'Why is the plant in the background?   The reflections along the top and left are a bit distracting to this interesting subject.', '2003-06-09 18:47:07.000000', NULL, 1),
(319977, 23836, 7711, '<td valign="top">i don''t like the pink light near the top, it doesn''t really seem to have a purpose.</td>', 'i don''t like the pink light near the top, it doesn''t really seem to have a purpose.', '2003-06-09 18:47:28.000000', NULL, 1),
(319978, 23687, 6870, '<td valign="top">Nice composition. The paper and other object give the photo some context, which really enhances it, I feel. I wish the coffee cup were more in focus all around, but especially in that central edge, which is where my eye seems to be led.</td>', 'Nice composition. The paper and other object give the photo some context, which really enhances it, I feel. I wish the coffee cup were more in focus all around, but especially in that central edge, which is where my eye seems to be led.', '2003-06-09 18:47:32.000000', NULL, 1),
