(320854, 23779, 9297, '<td valign="top">Nice focus-work!<br/> <br/>I love the way you''ve caught the different textures of the wax at different stages of melted.</td>', 'Nice focus-work! I love the way you''ve caught the different textures of the wax at different stages of melted.', '2003-06-10 17:29:12.000000', NULL, 1),
