INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(320893, 23222, 4400, '<td valign="top">Brilliant! I thing this will go to the topp,    10</td>', 'Brilliant! I thing this will go to the topp,    10', '2003-06-10 18:23:53.000000', NULL, 1),
(320895, 23774, 4400, '<td valign="top">I like the lighting <br/> <br/></td>', 'I like the lighting  ', '2003-06-10 18:32:58.000000', NULL, 1),
(320901, 23835, 4400, '<td valign="top">nice one! good focus I like the bubble and colour  10pt</td>', 'nice one! good focus I like the bubble and colour  10pt', '2003-06-10 18:56:37.000000', NULL, 1),
(320926, 23800, 527, '<td valign="top">Very interesting. This is an excellent example of effective cropping. I''m not sure in what manner you did the soft lighting but I like it. It is simply a fun picture to study with the interesting shapes and colors.</td>', 'Very interesting. This is an excellent example of effective cropping. I''m not sure in what manner you did the soft lighting but I like it. It is simply a fun picture to study with the interesting shapes and colors.', '2003-06-10 19:44:28.000000', NULL, 1),
(320927, 23813, 527, '<td valign="top">This is very well done and fun to study. Nice composition, textures, and colors.</td>', 'This is very well done and fun to study. Nice composition, textures, and colors.', '2003-06-10 19:46:50.000000', NULL, 1),
(320931, 23522, 527, '<td valign="top">It''s an intersting photo but I do not like the placement of the yellow portion. i find it distracting. If that color was used in a different manner such as part of a color blend or fade in the background then I think it would have been more effective. I like the composition.</td>', 'It''s an intersting photo but I do not like the placement of the yellow portion. i find it distracting. If that color was used in a different manner such as part of a color blend or fade in the background then I think it would have been more effective. I like the composition.', '2003-06-10 19:50:08.000000', NULL, 1),
(320933, 23796, 527, '<td valign="top">First off, this is amazing and I can''t wait to read about how you did it. It very well could be the winner. I do have a few quibbles, though. The way the bottom of the blender is cut off bothers me a little. I think I would rather see the whole base or have it cut off just below the glass portion. I''m still wondering about the background color, however, it is very bold which is very effective. Excellent job. -T</td>', 'First off, this is amazing and I can''t wait to read about how you did it. It very well could be the winner. I do have a few quibbles, though. The way the bottom of the blender is cut off bothers me a little. I think I would rather see the whole base or have it cut off just below the glass portion. I''m still wondering about the background color, however, it is very bold which is very effective. Excellent job. -T', '2003-06-10 19:56:15.000000', NULL, 1),
(320935, 23830, 527, '<td valign="top">I like this concept very much but I feel that it would be even more effective with a longer format. I would enjoy seeing more of the oil flowing off of the corn. Very well done. -T</td>', 'I like this concept very much but I feel that it would be even more effective with a longer format. I would enjoy seeing more of the oil flowing off of the corn. Very well done. -T', '2003-06-10 20:06:06.000000', NULL, 1),
(320946, 23635, 2158, '<td valign="top">I want some...</td>', 'I want some...', '2003-06-10 20:40:12.000000', NULL, 1),
(320949, 23786, 9303, '<td valign="top">this is a wonderful photo, the transparency with the slight opaque nature and the textures and movement.</td>', 'this is a wonderful photo, the transparency with the slight opaque nature and the textures and movement.', '2003-06-10 20:43:09.000000', NULL, 1),
(320957, 23211, 1570, '<td valign="top">dramatic macro, 8</td>', 'dramatic macro, 8', '2003-06-10 21:03:44.000000', NULL, 1),
(320958, 23522, 1570, '<td valign="top">this is dramatic, but i wish there was no yellow on the background...</td>', 'this is dramatic, but i wish there was no yellow on the background...', '2003-06-10 21:05:16.000000', NULL, 1),
(320961, 23710, 7151, '<td valign="top">Can''t see any liquid connection.  As a building interior, it''s maybe average, lighting isn''t very good and it''s not real sharp.  1</td>', 'Can''t see any liquid connection.  As a building interior, it''s maybe average, lighting isn''t very good and it''s not real sharp.  1', '2003-06-10 21:14:14.000000', NULL, 1),
(320962, 23506, 7151, '<td valign="top">Can''t see any liquid connection.  Seems more digital art than a photograph.  Maybe the description will shed some light?  1</td>', 'Can''t see any liquid connection.  Seems more digital art than a photograph.  Maybe the description will shed some light?  1', '2003-06-10 21:15:25.000000', NULL, 1),
(320963, 23497, 7151, '<td valign="top">Can''t see any liquid connection.  In fact, can''t see much of anything.  Not sure what you were going for here.  1</td>', 'Can''t see any liquid connection.  In fact, can''t see much of anything.  Not sure what you were going for here.  1', '2003-06-10 21:16:11.000000', NULL, 1),
(320965, 23760, 7151, '<td valign="top">Can''t see any liquid connection.  As a kite, it''s sort of interesting, but a lot of empty space.  The sky is kind of noisy.  The main kite is just really tiny.  1</td>', 'Can''t see any liquid connection.  As a kite, it''s sort of interesting, but a lot of empty space.  The sky is kind of noisy.  The main kite is just really tiny.  1', '2003-06-10 21:17:06.000000', NULL, 1),
(320967, 23215, 7151, '<td valign="top">Can''t see any liquid connection.  As a building shot, its a very interesting perspective, though just a bit dark.  Maybe another time of day.  2</td>', 'Can''t see any liquid connection.  As a building shot, its a very interesting perspective, though just a bit dark.  Maybe another time of day.  2', '2003-06-10 21:18:28.000000', NULL, 1),
(320968, 23759, 7151, '<td valign="top">No water, and no liquid to be seen.  The lighting is really harsh, and the DOF is a bit too narrow.  2</td>', 'No water, and no liquid to be seen.  The lighting is really harsh, and the DOF is a bit too narrow.  2', '2003-06-10 21:19:13.000000', NULL, 1),
(320969, 23375, 7151, '<td valign="top">Can''t see any liquid connection.  Well, ok maybe liquid as an adjective?  Still doesn''t work for me.  The lighting is too dark and the focus isn''t very sharp.  An OK job of stopping the motion.  2</td>', 'Can''t see any liquid connection.  Well, ok maybe liquid as an adjective?  Still doesn''t work for me.  The lighting is too dark and the focus isn''t very sharp.  An OK job of stopping the motion.  2', '2003-06-10 21:21:06.000000', NULL, 1),
(320970, 23747, 7151, '<td valign="top">Can''t see any liquid connection.  Looks solid to me.  I bit soft, kind of a detracting background.  2</td>', 'Can''t see any liquid connection.  Looks solid to me.  I bit soft, kind of a detracting background.  2', '2003-06-10 21:22:06.000000', NULL, 1),
(320972, 23806, 7151, '<td valign="top">Liquid, yeah, but just no appeal for me.  Ya takes your chances...  2</td>', 'Liquid, yeah, but just no appeal for me.  Ya takes your chances...  2', '2003-06-10 21:23:02.000000', NULL, 1),
(320973, 23449, 7151, '<td valign="top">I want to see the liquid, not what it "sees".  It may just be the distortions from the glass, but there''s no good focus.  An extra point for a different idea.  2</td>', 'I want to see the liquid, not what it "sees".  It may just be the distortions from the glass, but there''s no good focus.  An extra point for a different idea.  2', '2003-06-10 21:24:36.000000', NULL, 1),
(320974, 23490, 7151, '<td valign="top">Will be beer (some of it anyway) - is water...  As a photo, doesn''t really offer much beyond a snapshot with a clever title. 2</td>', 'Will be beer (some of it anyway) - is water...  As a photo, doesn''t really offer much beyond a snapshot with a clever title. 2', '2003-06-10 21:24:54.000000', NULL, 1),
(320975, 23187, 7151, '<td valign="top">I either don''t get the connection, or that''s water.  Or, I don''t know what I''m looking at?  In any case, no liquid connection for me.  The colors are kind of nice, but still a bit muted, its pretty noisy, and the focus is very soft.  2</td>', 'I either don''t get the connection, or that''s water.  Or, I don''t know what I''m looking at?  In any case, no liquid connection for me.  The colors are kind of nice, but still a bit muted, its pretty noisy, and the focus is very soft.  2', '2003-06-10 21:26:42.000000', NULL, 1),
(320976, 23699, 7151, '<td valign="top">Looks like water to me.  If it''s not, then it wasn''t communicated well.  Framing is OK, color is nice, if a little dark, and focus is good.  2</td>', 'Looks like water to me.  If it''s not, then it wasn''t communicated well.  Framing is OK, color is nice, if a little dark, and focus is good.  2', '2003-06-10 21:27:47.000000', NULL, 1),
(320979, 23346, 7151, '<td valign="top">I guess flow is supposed to indicate the reflection?  The tilt of the building?  Not sure, but it doesn''t convey liquid to me.  a fairly interesting shot on its own, though the colors are muted and it''s a bit grainy.  Better weather or time of day might have helped.  2</td>', 'I guess flow is supposed to indicate the reflection?  The tilt of the building?  Not sure, but it doesn''t convey liquid to me.  a fairly interesting shot on its own, though the colors are muted and it''s a bit grainy.  Better weather or time of day might have helped.  2', '2003-06-10 21:29:28.000000', NULL, 1),
(320980, 23717, 7151, '<td valign="top">Not sure what this is, but it only maybe looks vaguely liquidy, but not convincingly.  The focus is pretty soft, the lighting is pretty dar, and the background isn''t too appealing.  2</td>', 'Not sure what this is, but it only maybe looks vaguely liquidy, but not convincingly.  The focus is pretty soft, the lighting is pretty dar, and the background isn''t too appealing.  2', '2003-06-10 21:31:15.000000', NULL, 1),
(320982, 23596, 7151, '<td valign="top">A liquid seems implied at best.  The shot is pretty unappealing for me, lacking any contrast or depth.  There''s no real focus and it''s pretty grainy.  The keyboard background is hard to understand. 2</td>', 'A liquid seems implied at best.  The shot is pretty unappealing for me, lacking any contrast or depth.  There''s no real focus and it''s pretty grainy.  The keyboard background is hard to understand. 2', '2003-06-10 21:34:13.000000', NULL, 1),
(320984, 23770, 7151, '<td valign="top">Yeah, it''s a little liquidy.  But, the focus is off, the lighting is pretty harsh, and the background is "messy".  Nice capture on the steam though!  3</td>', 'Yeah, it''s a little liquidy.  But, the focus is off, the lighting is pretty harsh, and the background is "messy".  Nice capture on the steam though!  3', '2003-06-10 21:35:33.000000', NULL, 1),
(320987, 23510, 7151, '<td valign="top">I''ll take your word that it''s honey, but the focus is so off there''s nothing to really see.  Looks like there might have been some interesting motion going on there, but it wasn''t captured very well.  3</td>', 'I''ll take your word that it''s honey, but the focus is so off there''s nothing to really see.  Looks like there might have been some interesting motion going on there, but it wasn''t captured very well.  3', '2003-06-10 21:37:39.000000', NULL, 1),
(320989, 23732, 7151, '<td valign="top">OK, a fizzy liquid.  It''s not too recognizable down in the bottles.  Also, the phot is very pixelated and noisy.  Because of that it''s hard to tell, but the focus doesn''t look very sharp.  Not sure what the ruler is there for.  3</td>', 'OK, a fizzy liquid.  It''s not too recognizable down in the bottles.  Also, the phot is very pixelated and noisy.  Because of that it''s hard to tell, but the focus doesn''t look very sharp.  Not sure what the ruler is there for.  3', '2003-06-10 21:39:21.000000', NULL, 1),
(320991, 23643, 7151, '<td valign="top">I bumped you from a 3 to a 4 at the last minute, because I assume that''s a pool of oil there.  The fact that I missed it before pretty much tells the story why it didn''t do better - the focus is way to blurry on the oil.  Perhas a change of angle, some better lighting, and a little work on the focus would have improved the presentation.  4</td>', 'I bumped you from a 3 to a 4 at the last minute, because I assume that''s a pool of oil there.  The fact that I missed it before pretty much tells the story why it didn''t do better - the focus is way to blurry on the oil.  Perhas a change of angle, some better lighting, and a little work on the focus would have improved the presentation.  4', '2003-06-10 21:41:48.000000', NULL, 1),
(320992, 23330, 9303, '<td valign="top">I feel this photo is a bit to trite and unimaginative--thre must be ove a million shots of coke pouringinto a glass.</td>', 'I feel this photo is a bit to trite and unimaginative--thre must be ove a million shots of coke pouringinto a glass.', '2003-06-10 21:42:47.000000', NULL, 1),
(320995, 23803, 9303, '<td valign="top">the mysterious liquid, the shadow and light!  This photo is just imbued with a sense of impending '' something''  Is it poison?  is it a warm drink for someone who has taken ill in the middle of the night? Is it a liqueur at a fancy dining spot, or a tacky waterfront bar?  Wonderful!</td>', 'the mysterious liquid, the shadow and light!  This photo is just imbued with a sense of impending '' something''  Is it poison?  is it a warm drink for someone who has taken ill in the middle of the night? Is it a liqueur at a fancy dining spot, or a tacky waterfront bar?  Wonderful!', '2003-06-10 21:44:33.000000', NULL, 1),
(320996, 23173, 7151, '<td valign="top">My highest rated non-liquid score of the week.  Gave you an extra point for the humor and the decent job you did with your idea.  There''s still something in the colors - maybe too pink, too washed out, just not sure - that makes the whole shot not appeal a lot to me.  4</td>', 'My highest rated non-liquid score of the week.  Gave you an extra point for the humor and the decent job you did with your idea.  There''s still something in the colors - maybe too pink, too washed out, just not sure - that makes the whole shot not appeal a lot to me.  4', '2003-06-10 21:44:37.000000', NULL, 1),
(320997, 23506, 9303, '<td valign="top">Now.  I LOVE this photo, its magical, colorful and oh, so creative!  however, I don''t see clearly how it fits into the ''liquid'' category.....</td>', 'Now.  I LOVE this photo, its magical, colorful and oh, so creative!  however, I don''t see clearly how it fits into the ''liquid'' category.....', '2003-06-10 21:45:12.000000', NULL, 1),
(320998, 23784, 7151, '<td valign="top">OK, you got a non-water liquid, oil of some kind, mixed in there, but the shot just doesn''t work well.  Lighting, focus, background - some or all of those, and maybe more, combine to just make this not work very well.  3</td>', 'OK, you got a non-water liquid, oil of some kind, mixed in there, but the shot just doesn''t work well.  Lighting, focus, background - some or all of those, and maybe more, combine to just make this not work very well.  3', '2003-06-10 21:45:56.000000', NULL, 1),
(320999, 23713, 9303, '<td valign="top">there is a market lack of creativity here..perhaps pouring the milk all over the body of a person would have been more interesting.</td>', 'there is a market lack of creativity here..perhaps pouring the milk all over the body of a person would have been more interesting.', '2003-06-10 21:46:08.000000', NULL, 1),
